// ============================================================
// VALIDER LA REQUÊTE — whisper-local (azy.daily#421, contrat #296)
// ============================================================
// Ce workflow ne transcrit pas : le service de prod001 va chercher l'audio, transcrit et
// fait LUI-MÊME le rappel signé vers callback_url. n8n valide, relaie verbatim, répond 202
// et n'intervient plus — SAUF si la soumission échoue : dans ce cas le service n'a jamais
// accepté le job, personne ne rappellera, et c'est à nous d'émettre l'échec signé.

const entree = $input.first().json;
const body = entree && entree.body && typeof entree.body === 'object' && !Array.isArray(entree.body)
  ? entree.body
  : (entree && typeof entree === 'object' ? entree : {});

const erreurs = [];
const champs = [];
const refuser = (champ, message) => { champs.push(champ); erreurs.push(message); };
const absent = v => v === undefined || v === null || v === '';

const texteRequis = nom => {
  const v = body[nom];
  if (absent(v) || typeof v !== 'string') { refuser(nom, `${nom} requis (chaîne non vide)`); return ''; }
  return v.trim();
};

const jobId = texteRequis('job_id');
const callbackUrl = texteRequis('callback_url');
const audioUrl = texteRequis('audio_url');
const mimeType = texteRequis('mime_type');
const model = texteRequis('model');

// https partout, sauf vers le réseau local : le service de prod001 et chat.api en dev
// s'appellent en http sur des noms .local. Tout le reste doit être chiffré.
const HTTPS = /^https:\/\/[^\s\/?#@]+([\/?#][^\s]*)?$/i;
const HTTP_LOCAL = /^http:\/\/([a-z0-9-]+\.local|localhost|127\.0\.0\.1|192\.168\.\d{1,3}\.\d{1,3})(:\d+)?([\/?#][^\s]*)?$/i;
const urlAcceptable = u => HTTPS.test(u) || HTTP_LOCAL.test(u);
if (callbackUrl && !urlAcceptable(callbackUrl)) refuser('callback_url', 'callback_url doit être https (ou http vers le réseau local)');
if (audioUrl && !urlAcceptable(audioUrl)) refuser('audio_url', 'audio_url doit être https (ou http vers le réseau local)');

// Modèles annoncés par infra le 23/09 : small | medium, préfixés faster-whisper- ou non.
// Un nom inconnu est refusé ICI plutôt que par le service : l'erreur nomme le champ et
// les valeurs acceptées, au lieu d'un transcription_model_unsupported en différé.
const MODELES = ['small', 'medium'];
const modeleNu = model.replace(/^faster-whisper-/i, '').toLowerCase();
if (model && !MODELES.includes(modeleNu)) {
  refuser('model', `model inconnu (${model.slice(0, 40)}), valeurs acceptées ${MODELES.join(' | ')} (préfixe faster-whisper- toléré)`);
}

let language = null;
if (!absent(body.language)) {
  if (typeof body.language !== 'string' || body.language.trim().length > 8) {
    refuser('language', 'language doit être une chaîne courte (ex. fr)');
  } else language = body.language.trim();
}

let durationSeconds = null;
if (!absent(body.duration_seconds)) {
  const n = typeof body.duration_seconds === 'string' && /^\d+(\.\d+)?$/.test(body.duration_seconds.trim())
    ? Number(body.duration_seconds) : body.duration_seconds;
  if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0) {
    refuser('duration_seconds', 'duration_seconds doit être un nombre positif');
  } else durationSeconds = n;
}

if (erreurs.length > 0) {
  return [{
    json: {
      valide: false,
      reponse: {
        success: false,
        job_id: jobId || null,
        error: { code: 'invalid_request', http_status: 400, message: erreurs.join(' ; '), fields: champs },
      },
    },
  }];
}

// Charge utile relayée VERBATIM au service : c'est le contrat #296, pas une interface à nous.
// On ne transmet ni api_key (le moteur est local, il n'en a pas) ni provider (le webhook EST
// le routage). Les champs facultatifs ne sont posés que s'ils existent.
const charge = { job_id: jobId, callback_url: callbackUrl, audio_url: audioUrl, mime_type: mimeType, model: model };
if (language !== null) charge.language = language;
if (durationSeconds !== null) charge.duration_seconds = durationSeconds;

return [{
  json: {
    valide: true,
    job_id: jobId,
    callback_url: callbackUrl,
    model: model,
    language: language,
    charge: charge,
    reponse: { success: true, job_id: jobId, status: 'accepted' },
  },
}];

// ============================================================
// CONSTRUIRE LE RAPPEL D'ÉCHEC — whisper-local (azy.daily#421)
// ============================================================
// N'est atteint QUE si la soumission au service a échoué. Le service n'a alors jamais
// accepté le job : il ne rappellera pas, et chat.api attendrait indéfiniment (les jobs
// orphelins ne rendent pas les crédits, azy.daily#422). C'est donc à nous d'émettre
// l'échec, signé comme n'importe quel rappel du contrat #296.
const req = $('Valider la requête').first().json;
const entree = $input.first().json || {};

// Liste FERMÉE du contrat #296 : un code hors liste casserait l'aiguillage des clients.
const CODES = ['file_too_large', 'unsupported_format', 'audio_unreadable', 'audio_too_long',
  'provider_unavailable', 'provider_auth', 'audio_fetch_failed', 'internal_error'];

const nettoyer = s => String(s === undefined || s === null ? '' : s)
  .replace(/\s+/g, ' ').trim().slice(0, 300);

const analyser = c => {
  if (c && typeof c === 'object') return c;
  if (typeof c === 'string') { try { return JSON.parse(c); } catch (e) { return { message: c }; } }
  return {};
};

// Statut HTTP : présent si le service a répondu ; absent sur une erreur de transport, et
// n8n ne laisse alors qu'un message « NNN - … » ou un code réseau (cf. n8n : onError masque
// le statut). http_status reste null quand il n'y a eu AUCUNE réponse — on ne l'invente pas.
let statut = null;
let message = '';
if (typeof entree.statusCode === 'number') {
  statut = entree.statusCode;
  const corps = analyser(entree.body !== undefined ? entree.body : entree.data);
  message = corps.message || corps.error || `HTTP ${statut}`;
} else if (entree.error !== undefined) {
  const e = entree.error && typeof entree.error === 'object' ? entree.error : { message: String(entree.error) };
  const brut = String(e.message || '');
  const m = brut.match(/^\s*(\d{3})\s*-\s*([\s\S]*)$/);
  if (m) { statut = Number(m[1]); message = m[2]; } else { message = brut || String(e.code || 'transport'); }
} else {
  message = 'réponse inattendue du service whisper-local';
}

// provider_auth si le service exige un jeton que nous n'avons pas (ou plus) ; sinon le
// service est en panne, injoignable ou refuse la charge : provider_unavailable.
const code = (statut === 401 || statut === 403) ? 'provider_auth' : 'provider_unavailable';

const corps = {
  success: false,
  job_id: req.job_id,
  error: {
    code: CODES.includes(code) ? code : 'internal_error',
    http_status: statut,
    provider_message: nettoyer(`whisper-local n'a pas accepté le job — ${message}`),
  },
  meta: { provider: 'whisper-local', model: req.model },
};

return [{ json: { job_id: req.job_id, callback_url: req.callback_url, corps_json: JSON.stringify(corps) } }];
